(function(root){"use strict";function freeze(value){if(value&&typeof value==="object"&&!Object.isFrozen(value)){Object.values(value).forEach(freeze);Object.freeze(value)}return value}const worlds=[{id:"meadow",number:1,name:"Twenty meadow",description:"Explore quantities and calculations to twenty.",color:"#8cab77",icon:"sprout"},{id:"number-trails",number:2,name:"Hundred trails",description:"Build and compare numbers to one hundred.",color:"#709cba",icon:"mountain"},{id:"mental-orchard",number:3,name:"Mental maths orchard",description:"Calculate with tens and ones.",color:"#d6936c",icon:"apple"},{id:"crossing-bridge",number:4,name:"Ten-crossing bridge",description:"Cross a ten and check with the opposite operation.",color:"#af99bf",icon:"bridge"},{id:"time-length",number:5,name:"Clock and ruler garden",description:"Read clocks and calendars, and compare lengths.",color:"#69a9ac",icon:"clock"},{id:"group-grove",number:6,name:"Equal-group grove",description:"Multiply, share, and make equal groups.",color:"#d3aa6f",icon:"tree"},{id:"table-trails",number:7,name:"Table trails",description:"Build multiplication facts from familiar groups.",color:"#8d9fb9",icon:"flower"},{id:"fact-stream",number:8,name:"Fact stream",description:"Explore zero, one, ten, and leftovers.",color:"#c18e9e",icon:"water"},{id:"problem-patch",number:9,name:"Problem-solving patch",description:"Split calculations, fill machines, and read data.",color:"#94ac84",icon:"compass"},{id:"discovery",number:10,name:"Discovery garden",description:"Explore measures, shapes, and larger numbers.",color:"#ad98c0",icon:"shapes"}];const levels=[{id:"g2-01",number:1,name:"Numbers to twenty",world:"meadow",type:"lesson",family:"quantity",skill:"Numbers to twenty",max:20,options:{mode:"mixed-representations"},objective:"I can match a picture with its number.",explanation:"A number tells how many apples or dots are shown. An empty picture means zero.",hints:["Count the apples or filled dots in the picture.","Match the amount to the number. If the picture is empty, the amount is zero."],commonMistakes:["Count the apples or dots, not the outline around them.","Moving objects apart does not change their number."]},{id:"g2-02",number:2,name:"Join to twenty",world:"meadow",type:"lesson",family:"add",skill:"Join to twenty",max:20,options:{mode:"picture-add"},objective:"I can combine two collections.",explanation:"Joining two collections gives their total. Make a complete ten when it helps.",hints:["Find how many more are needed to reach the next ten.","Split the amount added: reach the ten first, then add the rest."],commonMistakes:["Use every part of the amount added exactly once.","Check by subtracting one addend from the total."]},{id:"g2-03",number:3,name:"Take away to twenty",world:"meadow",type:"lesson",family:"subtract",skill:"Take away to twenty",max:20,options:{mode:"picture-subtract"},objective:"I can find what remains after objects leave.",explanation:"Start with the whole collection and remove the objects that leave. Count what remains.",hints:["Find how far the starting number is above the previous ten.","Split the amount removed: reach the ten first, then remove the rest."],commonMistakes:["Remove only the amount shown, without losing a part.","Check by adding the removed amount back."]},{id:"g2-04",number:4,name:"Complete the collection",world:"meadow",type:"lesson",family:"missing",skill:"Complete the collection",max:20,options:{mode:"target"},objective:"I can find how many apples are missing.",explanation:"Match each apple on the left to one on the right. The apples without a partner are the missing part.",hints:["Find one apple on the right for each apple on the left.","Count the apples on the right that have no partner."],commonMistakes:["Count the missing apples, not all the apples on the right.","The shown part and missing part together must make the target."]},{id:"g2-05",number:5,name:"Order and neighbours",world:"meadow",type:"lesson",family:"neighbours",skill:"Order and neighbours",max:20,options:{mode:"order-and-adjacent"},objective:"I can put numbers in order and find neighbours.",explanation:"Adjacent whole numbers differ by one. Moving right on a number line makes a number larger.",hints:["Locate the given number on the line.","For direct neighbours move one tick; for bounding tens find the two surrounding ten markers."],commonMistakes:["A direct neighbour is one away, not ten away.","For a number between decades use one lower and one higher ten."]},{id:"g2-06",number:6,name:"Picture stories",world:"meadow",type:"lesson",family:"picture-story",skill:"Picture stories",max:20,options:{mode:"join-or-leave"},objective:"I can choose the calculation that matches a picture.",explanation:"Two apple groups together mean addition. Birds flying away mean subtraction. Match the amounts and the sign to the picture.",hints:["For apples, count both groups. For birds, count all the birds first, then those flying away.","Choose + for the two apple groups or − for birds flying away. Check both numbers too."],commonMistakes:["In subtraction, start with every bird, including those flying away.","The sign and both numbers must match the picture, not only the final answer."]},{id:"g2-07",number:7,name:"Patterns and machines",world:"meadow",type:"lesson",family:"pattern",skill:"Patterns and machines",max:20,options:{mode:"patterns-and-machines"},objective:"I can continue a pattern and use a simple rule.",explanation:"Find what repeats or changes in the same way. Use that rule for the next place.",hints:["Find the shortest part that repeats, or compare two finished examples.","Apply exactly the same pattern or change to the unfinished place."],commonMistakes:["Repeat the whole pattern unit, not just its last picture.","One rule must work for every completed example."]},{id:"g2-08",number:8,name:"Meadow checkpoint",world:"meadow",type:"checkpoint",family:"mixed",skill:"Meadow checkpoint",max:20,options:{checkpoint:true,scope:"meadow"},objective:"I can use numbers and calculations to twenty.",explanation:"Choose the familiar picture or counting method that matches the task. Check the whole set before handing it in.",hints:["Choose the familiar model that fits this task.","Check the same answer with a second count, the opposite operation, or the unit relationship."],commonMistakes:["Answer the quantity indicated by the goal picture.","Keep the units and operation signs consistent."]},{id:"g2-09",number:9,name:"Counting tens",world:"number-trails",type:"lesson",family:"tens",skill:"Counting tens",max:100,options:{mode:"tens"},objective:"I can count in tens to one hundred.",explanation:"Each ten-value coin is worth ten ones. Count one group of ten for each coin.",hints:["Separate the ten-value coins and the one-value coins.","Match the tens first, then count the remaining ones."],commonMistakes:["Count the value of a coin rather than counting every coin as one.","The digit and the value of its position are different quantities."]},{id:"g2-10",number:10,name:"Tens and ones",world:"number-trails",type:"lesson",family:"place",skill:"Tens and ones",max:100,options:{mode:"build"},objective:"I can tell how many tens and ones a number has.",explanation:"The first digit counts the tens, and the second counts the ones. Give the two counts separately.",hints:["Read the tens digit first.","Then read the ones digit; use zero when there are no ones."],commonMistakes:["Give the number of tens, not their full value.","Write each digit in the field with the matching counter."]},{id:"g2-11",number:11,name:"One number, many pictures",world:"number-trails",type:"lesson",family:"representations",skill:"One number, many pictures",max:100,options:{mode:"match"},objective:"I can recognise the same quantity in different pictures.",explanation:"Different arrangements can show the same number. Match the tens first, then the ones.",hints:["Separate the ten-value coins and the one-value coins.","Match the tens first, then count the remaining ones."],commonMistakes:["Count the value of a coin rather than counting every coin as one.","The digit and the value of its position are different quantities."]},{id:"g2-12",number:12,name:"Smaller, greater, equal",world:"number-trails",type:"lesson",family:"compare",skill:"Smaller, greater, equal",max:100,options:{},objective:"I can choose the correct comparison sign.",explanation:"Compare the tens first. If they match, compare the ones. Equal numbers use the equals sign.",hints:["Compare the tens digits first.","If the tens match, compare the ones; use the equals sign when both numbers match."],commonMistakes:["The open side of the comparison sign faces the greater quantity.","Different-looking pictures can still show equal quantities."]},{id:"g2-13",number:13,name:"Number and ten neighbours",world:"number-trails",type:"lesson",family:"neighbours",skill:"Number and ten neighbours",max:100,options:{mode:"adjacent-and-bounding-tens",excludeExactTens:true},objective:"I can find nearby numbers and surrounding tens.",explanation:"The direct neighbours are one less and one more. A number between decades sits between its lower and upper ten.",hints:["Locate the given number on the line.","For direct neighbours move one tick; for bounding tens find the two surrounding ten markers."],commonMistakes:["A direct neighbour is one away, not ten away.","For a number between decades use one lower and one higher ten."]},{id:"g2-14",number:14,name:"Even and odd",world:"number-trails",type:"lesson",family:"parity",skill:"Even and odd",max:100,options:{mode:"pair-and-last-digit"},objective:"I can decide whether a number is even or odd.",explanation:"Make pairs. An even collection has no object left over; an odd collection has one.",hints:["Make pairs without using an object twice.","Look for a single object left over, then compare with the final digit."],commonMistakes:["No leftover means even; one leftover means odd.","Only the last digit determines whether a whole number is even or odd."]},{id:"g2-15",number:15,name:"Hundred-chart paths",world:"number-trails",type:"lesson",family:"hundred-chart",skill:"Hundred-chart paths",max:100,options:{steps:[1,10]},objective:"I can move by one or ten on a hundred chart.",explanation:"A horizontal step changes the number by one. A vertical step changes it by ten.",hints:["Find the starting square on the chart.","Follow each shown horizontal or vertical step in order."],commonMistakes:["A row change is ten, while one step along a row is one.","Do not count the starting square as an extra step."]},{id:"g2-16",number:16,name:"Number-trail checkpoint",world:"number-trails",type:"checkpoint",family:"mixed",skill:"Number-trail checkpoint",max:100,options:{checkpoint:true,scope:"number-trails"},objective:"I can build, compare, and locate numbers to one hundred.",explanation:"Use tens and ones, pairs, or a number line to match the task. Keep the same value in every representation.",hints:["Choose the familiar model that fits this task.","Check the same answer with a second count, the opposite operation, or the unit relationship."],commonMistakes:["Answer the quantity indicated by the goal picture.","Keep the units and operation signs consistent."]},{id:"g2-17",number:17,name:"Round tens",world:"mental-orchard",type:"lesson",family:"round-tens",skill:"Round tens",max:100,options:{mode:"mixed"},objective:"I can add and subtract complete tens.",explanation:"Calculate with the number of tens, then keep their value of ten each.",hints:["Count how many complete tens are being added or removed.","Move that many ten-value coins while preserving every loose one."],commonMistakes:["A ten-value coin changes the total by ten.","Adding or removing whole tens does not change the ones digit here."]},{id:"g2-18",number:18,name:"Add the ones",world:"mental-orchard",type:"lesson",family:"add",skill:"Add the ones",max:100,options:{mode:"ones-no-cross"},objective:"I can add ones without crossing a ten.",explanation:"Keep the tens and combine only the ones. These tasks do not make another full ten.",hints:["Leave the tens in place.","Combine the loose ones, then reconnect them with the unchanged tens."],commonMistakes:["Only the ones change in these tasks.","Keep every original ten in the final amount."]},{id:"g2-19",number:19,name:"Take away the ones",world:"mental-orchard",type:"lesson",family:"subtract",skill:"Take away the ones",max:100,options:{mode:"ones-no-cross"},objective:"I can subtract ones without opening a ten.",explanation:"Keep the tens and remove the loose ones. There are enough ones without changing a ten.",hints:["Leave the tens in place.","Remove the shown number of loose ones and count those remaining."],commonMistakes:["Remove ones only; the tens stay unchanged.","Check that the removed ones and remaining ones make the starting ones."]},{id:"g2-20",number:20,name:"Change the tens",world:"mental-orchard",type:"lesson",family:"tens-change",skill:"Change the tens",max:100,options:{mode:"tens"},objective:"I can add and subtract tens while keeping the ones.",explanation:"Move whole tens. The ones stay the same because no single ones are added or removed.",hints:["Count how many complete tens are being added or removed.","Move that many ten-value coins while preserving every loose one."],commonMistakes:["A ten-value coin changes the total by ten.","Adding or removing whole tens does not change the ones digit here."]},{id:"g2-21",number:21,name:"Tens with tens, ones with ones",world:"mental-orchard",type:"lesson",family:"no-cross",skill:"Tens with tens, ones with ones",max:100,options:{mode:"mixed-no-cross"},objective:"I can calculate with two-digit numbers without crossing a ten.",explanation:"Combine or remove tens and ones separately, then join their values again.",hints:["Separate tens from ones in both numbers.","Calculate each place separately, then reconnect the two parts."],commonMistakes:["Add or remove each place with the matching place.","Keep the values of the tens and ones distinct."]},{id:"g2-22",number:22,name:"Garden tokens",world:"mental-orchard",type:"lesson",family:"money",skill:"Garden tokens",max:100,options:{mode:"fictional-tokens",cashStep:10},objective:"I can make an amount and find what is left after paying.",explanation:"Each pictured token has its written value. Add token values or take the price away from the amount paid.",hints:["Read each token value and group equal values.","Combine the values, or count from the price up to the amount paid."],commonMistakes:["The number of tokens is not necessarily their total value.","Payment minus price gives the amount left or returned."]},{id:"g2-23",number:23,name:"Roman number cards",world:"mental-orchard",type:"lesson",family:"roman",skill:"Roman number cards",max:100,options:{maxRoman:20},objective:"I can read Roman numerals through twenty.",explanation:"I is one, V is five, and X is ten. IV is one before five; IX is one before ten.",hints:["Match I with one, V with five, and X with ten.","Build the value; I before V or X means one less than that symbol."],commonMistakes:["IV means four and IX means nine.","XX contains two tens, so it means twenty."]},{id:"g2-24",number:24,name:"Orchard checkpoint",world:"mental-orchard",type:"checkpoint",family:"mixed",skill:"Orchard checkpoint",max:100,options:{checkpoint:true,scope:"mental-orchard"},objective:"I can use mental calculation and number representations.",explanation:"Choose tens and ones, tokens, or Roman number cards as the task requires.",hints:["Choose the familiar model that fits this task.","Check the same answer with a second count, the opposite operation, or the unit relationship."],commonMistakes:["Answer the quantity indicated by the goal picture.","Keep the units and operation signs consistent."]},{id:"g2-25",number:25,name:"Add across a ten",world:"crossing-bridge",type:"lesson",family:"add",skill:"Add across a ten",max:100,options:{mode:"cross-one-ten"},objective:"I can reach the next ten before adding the rest.",explanation:"Split the amount being added. First reach the next full ten, then add the rest.",hints:["Find how many more are needed to reach the next ten.","Split the amount added: reach the ten first, then add the rest."],commonMistakes:["Use every part of the amount added exactly once.","Check by subtracting one addend from the total."]},{id:"g2-26",number:26,name:"Subtract across a ten",world:"crossing-bridge",type:"lesson",family:"subtract",skill:"Subtract across a ten",max:100,options:{mode:"cross-one-ten"},objective:"I can reach the previous ten before subtracting the rest.",explanation:"Split the amount being taken away. Reach the previous full ten first, then subtract the rest.",hints:["Find how far the starting number is above the previous ten.","Split the amount removed: reach the ten first, then remove the rest."],commonMistakes:["Remove only the amount shown, without losing a part.","Check by adding the removed amount back."]},{id:"g2-27",number:27,name:"Add two-digit numbers",world:"crossing-bridge",type:"lesson",family:"add",skill:"Add two-digit numbers",max:100,options:{mode:"two-digit"},objective:"I can split a two-digit addend into tens and ones.",explanation:"Split the second number into tens and ones. Add the tens first, then the ones.",hints:["Split the second number into tens and ones.","Add the tens and then the ones; subtract the second number to check."],commonMistakes:["Keep all parts of the second number when splitting.","The inverse check should return the first number."]},{id:"g2-28",number:28,name:"Subtract two-digit numbers",world:"crossing-bridge",type:"lesson",family:"subtract",skill:"Subtract two-digit numbers",max:100,options:{mode:"two-digit"},objective:"I can split a two-digit number to subtract and check.",explanation:"Split the number being taken away into tens and ones. Subtract the tens first, then the ones.",hints:["Split the amount removed into tens and ones.","Subtract the tens and then the ones; add the amount back to check."],commonMistakes:["Use subtraction for both parts of the removed amount.","Adding the removed amount back should recover the start."]},{id:"g2-29",number:29,name:"Start at a round ten",world:"crossing-bridge",type:"lesson",family:"subtract",skill:"Start at a round ten",max:100,options:{mode:"round-start"},objective:"I can subtract from a round ten or one hundred.",explanation:"Split the amount removed into tens and ones. A ten can be changed into ten ones when needed.",hints:["Split the amount removed into tens and ones.","Subtract the tens and then the ones; add the amount back to check."],commonMistakes:["Use subtraction for both parts of the removed amount.","Adding the removed amount back should recover the start."]},{id:"g2-30",number:30,name:"Inside the brackets",world:"crossing-bridge",type:"lesson",family:"brackets",skill:"Inside the brackets",max:100,options:{mode:"add-subtract"},objective:"I can complete the bracketed calculation first.",explanation:"Brackets keep quantities together. Work out that group before the outside operation.",hints:["Outline the quantities held together by the brackets.","Calculate that group first, then complete the outside operation."],commonMistakes:["Brackets come before the outer calculation.","Keep the operation outside the brackets unchanged."]},{id:"g2-31",number:31,name:"Missing amounts",world:"crossing-bridge",type:"lesson",family:"picture-story",skill:"Two-step picture stories",max:100,options:{structures:["successive-changes","comparison","unknown-start","comparison-and-total"]},objective:"I can find the missing quantity in a picture.",explanation:"Find what the picture asks for. If it takes more than one step, use the first result in the next step.",hints:["Follow the picture from the start through each change.","If there are several steps, keep each intermediate result for the next one."],commonMistakes:["A pictured goal may ask for a missing part rather than the final total.","Use each change once and keep track of what is known."]},{id:"g2-32",number:32,name:"Bridge checkpoint",world:"crossing-bridge",type:"checkpoint",family:"mixed",skill:"Bridge checkpoint",max:100,options:{checkpoint:true,scope:"crossing-bridge"},objective:"I can calculate across tens and check in the opposite direction.",explanation:"Check an addition by subtraction and a subtraction by addition. The check should recover a starting quantity.",hints:["Choose the familiar model that fits this task.","Check the same answer with a second count, the opposite operation, or the unit relationship."],commonMistakes:["Answer the quantity indicated by the goal picture.","Keep the units and operation signs consistent."]},{id:"g2-33",number:33,name:"Calendar pictures",world:"time-length",type:"lesson",family:"calendar",skill:"Calendar pictures",max:100,options:{mode:"dates-cycles"},objective:"I can find dates and follow the order of months and seasons.",explanation:"Each calendar square is one day. Months and seasons repeat in a fixed order.",hints:["Find the marked date, month or season.","Count the needed days, or follow the cycle to the next month or season."],commonMistakes:["When counting days, count moves, not the starting day.","After the last month or season, the cycle starts again."]},{id:"g2-34",number:34,name:"Whole hours through the day",world:"time-length",type:"lesson",family:"clock",skill:"Whole hours through the day",max:100,options:{mode:"whole-hours"},objective:"I can match whole-hour clocks with times of day.",explanation:"The short hand shows the hour. At a whole hour the long hand points to twelve.",hints:["Read the short hand to find the hour interval.","Follow the long hand in five-minute groups, then count any extra minute marks."],commonMistakes:["The short hand moves gradually as minutes pass.","Each step between hour numbers on the minute scale is five minutes."]},{id:"g2-35",number:35,name:"Minutes on the clock",world:"time-length",type:"lesson",family:"clock",skill:"Minutes on the clock",max:100,options:{mode:"five-then-one-minute"},objective:"I can read minutes in steps of five and one.",explanation:"Between neighbouring hour numbers there are five minutes. The short hand moves gradually as minutes pass.",hints:["Read the short hand to find the hour interval.","Follow the long hand in five-minute groups, then count any extra minute marks."],commonMistakes:["The short hand moves gradually as minutes pass.","Each step between hour numbers on the minute scale is five minutes."]},{id:"g2-36",number:36,name:"Quarter, half, three quarters",world:"time-length",type:"lesson",family:"clock",skill:"Quarter, half, three quarters",max:100,options:{mode:"quarters",minutes:[15,30,45]},objective:"I can recognise fifteen, thirty, and forty-five minutes.",explanation:"A quarter of an hour is 15 minutes, half is 30, and three quarters is 45. The hands keep moving together.",hints:["Read the short hand to find the hour interval.","Follow the long hand in five-minute groups, then count any extra minute marks."],commonMistakes:["The short hand moves gradually as minutes pass.","Each step between hour numbers on the minute scale is five minutes."]},{id:"g2-37",number:37,name:"How much time passes?",world:"time-length",type:"lesson",family:"elapsed",skill:"How much time passes?",max:100,options:{mode:"across-hour",maxDuration:100},objective:"I can find how many minutes pass between two times.",explanation:"Count from the starting time to the finishing time. If you pass a whole hour, you can count in two parts.",hints:["Find the starting and finishing times.","Count the five-minute intervals. If you pass a whole hour, add the two parts."],commonMistakes:["Count the intervals, not the starting mark.","One hour contains sixty minutes."]},{id:"g2-38",number:38,name:"Measure the length",world:"time-length",type:"lesson",family:"measure-length",skill:"Measure the length",max:100,options:{units:["cm","dm","m"],fixedScale:true},objective:"I can read a length on a ruler.",explanation:"The ribbon starts at zero. Read where its other end meets the scale.",hints:["Find zero and the end of the ribbon.","Follow the ribbon's end down to the scale. One full interval is one unit."],commonMistakes:["Count unit intervals rather than marks.","Use the unit written on the ruler."]},{id:"g2-39",number:39,name:"Centimetres, decimetres, metres",world:"time-length",type:"lesson",family:"convert-length",skill:"Centimetres, decimetres, metres",max:100,options:{units:["cm","dm","m"],maxResult:100},objective:"I can convert between cm, dm and m.",explanation:"One decimetre is ten centimetres. One metre is ten decimetres or one hundred centimetres.",hints:["Read the given unit and the unit needed in the answer.","Count ten smaller units for each larger one. When changing back, make complete groups of ten."],commonMistakes:["The number changes when the unit changes; the length stays the same.","For a mixed length, include both the decimetres and the extra centimetres."]},{id:"g2-40",number:40,name:"Clock-and-ruler checkpoint",world:"time-length",type:"checkpoint",family:"mixed",skill:"Clock-and-ruler checkpoint",max:100,options:{checkpoint:true,scope:"time-length"},objective:"I can use calendars, clocks, durations, and lengths.",explanation:"Use a calendar for dates, a clock or timeline for time, and a ruler or unit diagram for length.",hints:["Choose the familiar model that fits this task.","Check the same answer with a second count, the opposite operation, or the unit relationship."],commonMistakes:["Answer the quantity indicated by the goal picture.","Keep the units and operation signs consistent."]},{id:"g2-41",number:41,name:"Equal groups",world:"group-grove",type:"lesson",family:"equal-groups",skill:"Equal groups",max:100,options:{mode:"repeated-addition"},objective:"I can count all the counters in equal groups.",explanation:"Count the counters in one group. Add the same amount for each next group.",hints:["Count the counters in one group first.","Add that amount again for each next group."],commonMistakes:["Count every group once.","Give the total number of counters, not the number of groups."]},{id:"g2-42",number:42,name:"Rows and columns",world:"group-grove",type:"lesson",family:"array",skill:"Rows and columns",max:100,options:{mode:"turn-array"},objective:"I can count squares by rows and columns.",explanation:"Count the squares in one row. Add that amount for each next row. Counting by columns gives the same total.",hints:["Count the squares in one row first.","Add the same amount for each next row, keeping track of the rows."],commonMistakes:["Give the total number of squares, not just the number of rows.","Recount by columns to check the total."]},{id:"g2-43",number:43,name:"Share equally",world:"group-grove",type:"lesson",family:"sharing",skill:"Share equally",max:100,options:{mode:"sharing"},objective:"I can find how many objects each recipient gets.",explanation:"The number of recipients is given. Give one object to each in turn until all objects are shared equally.",hints:["Find the known number of recipients.","Give one object to each in every round, then inspect the contents of one share."],commonMistakes:["The answer is the amount in one share.","Sharing fairly means every recipient gets the same amount."]},{id:"g2-44",number:44,name:"Pack equal groups",world:"group-grove",type:"lesson",family:"grouping",skill:"Pack equal groups",max:100,options:{mode:"grouping"},objective:"I can find how many complete groups can be made.",explanation:"The size of each group is given. Fill one group at a time, then count the full groups.",hints:["Find the known amount that belongs in one group.","Fill complete groups, then count how many full groups you made."],commonMistakes:["The answer is the number of groups, not the size written beside one group.","Use every object once when packing exact groups."]},{id:"g2-45",number:45,name:"Related calculations",world:"group-grove",type:"lesson",family:"fact-family",skill:"Related calculations",max:100,options:{mode:"inverse"},objective:"I can use multiplication and division for the same collection.",explanation:"The same collection connects its total, number of groups, and amount in each group.",hints:["Identify the total, group count, and amount in each group.","Use the two known quantities to rebuild the missing one; reverse the operation to check."],commonMistakes:["The position of the blank determines which quantity is requested.","Use a nonzero group size when dividing."]},{id:"g2-46",number:46,name:"Groups of two",world:"group-grove",type:"lesson",family:"table",skill:"Groups of two",max:100,options:{factor:2},objective:"I can multiply and divide by two.",explanation:"Make pairs to multiply by two. Count the pairs or find the amount in each equal share to divide.",hints:["Build the equal groups with a familiar arrangement.","Split larger groups into known smaller groups, or reverse the multiplication to divide."],commonMistakes:["The equal-group size and the number of groups play different roles.","A division check should rebuild the original total."]},{id:"g2-47",number:47,name:"Groups of three",world:"group-grove",type:"lesson",family:"table",skill:"Groups of three",max:100,options:{factor:3},objective:"I can multiply and divide by three.",explanation:"Multiply by three using three equal groups. For division, make groups of three or share into three equal groups.",hints:["Build the equal groups with a familiar arrangement.","Split larger groups into known smaller groups, or reverse the multiplication to divide."],commonMistakes:["The equal-group size and the number of groups play different roles.","A division check should rebuild the original total."]},{id:"g2-48",number:48,name:"Group-grove checkpoint",world:"group-grove",type:"checkpoint",family:"mixed",skill:"Group-grove checkpoint",max:100,options:{checkpoint:true,scope:"group-grove"},objective:"I can use equal groups, arrays, sharing, and facts for two and three.",explanation:"Decide whether the answer is a total, a number of groups, or the amount in one group.",hints:["Choose the familiar model that fits this task.","Check the same answer with a second count, the opposite operation, or the unit relationship."],commonMistakes:["Answer the quantity indicated by the goal picture.","Keep the units and operation signs consistent."]},{id:"g2-49",number:49,name:"Groups of four",world:"table-trails",type:"lesson",family:"table",skill:"Groups of four",max:100,options:{factor:4},objective:"I can multiply and divide by four.",explanation:"Four equal groups can be split into two groups and two more. Add the two totals.",hints:["Build the equal groups with a familiar arrangement.","Split larger groups into known smaller groups, or reverse the multiplication to divide."],commonMistakes:["The equal-group size and the number of groups play different roles.","A division check should rebuild the original total."]},{id:"g2-50",number:50,name:"Groups before adding",world:"table-trails",type:"lesson",family:"operation-order",skill:"Groups before adding",max:100,options:{mode:"multiply-before-add"},objective:"I can multiply before adding or subtracting.",explanation:"Work out the multiplication first. Use that result in the addition or subtraction.",hints:["Find the multiplication in the expression.","Replace the multiplication with its result, then finish the remaining calculation."],commonMistakes:["Do the multiplication before the + or − operation, even when it is written later.","Keep the original addition or subtraction sign for the last step."]},{id:"g2-51",number:51,name:"Groups of five",world:"table-trails",type:"lesson",family:"table",skill:"Groups of five",max:100,options:{factor:5},objective:"I can multiply and divide by five.",explanation:"Use groups of five. Two fives make ten, which can help you combine or split the groups.",hints:["Build the equal groups with a familiar arrangement.","Split larger groups into known smaller groups, or reverse the multiplication to divide."],commonMistakes:["The equal-group size and the number of groups play different roles.","A division check should rebuild the original total."]},{id:"g2-52",number:52,name:"Groups of six",world:"table-trails",type:"lesson",family:"table",skill:"Groups of six",max:100,options:{factor:6},objective:"I can multiply and divide by six.",explanation:"Count five equal groups, then add the counters in one more group.",hints:["Build the equal groups with a familiar arrangement.","Split larger groups into known smaller groups, or reverse the multiplication to divide."],commonMistakes:["The equal-group size and the number of groups play different roles.","A division check should rebuild the original total."]},{id:"g2-53",number:53,name:"Groups of seven",world:"table-trails",type:"lesson",family:"table",skill:"Groups of seven",max:100,options:{factor:7},objective:"I can multiply and divide by seven.",explanation:"Count five equal groups, then add the counters in two more groups.",hints:["Build the equal groups with a familiar arrangement.","Split larger groups into known smaller groups, or reverse the multiplication to divide."],commonMistakes:["The equal-group size and the number of groups play different roles.","A division check should rebuild the original total."]},{id:"g2-54",number:54,name:"Groups of eight",world:"table-trails",type:"lesson",family:"table",skill:"Groups of eight",max:100,options:{factor:8},objective:"I can multiply and divide by eight.",explanation:"Eight equal groups are two sets of four groups. Count one set and double its total.",hints:["Build the equal groups with a familiar arrangement.","Split larger groups into known smaller groups, or reverse the multiplication to divide."],commonMistakes:["The equal-group size and the number of groups play different roles.","A division check should rebuild the original total."]},{id:"g2-55",number:55,name:"Groups of nine",world:"table-trails",type:"lesson",family:"table",skill:"Groups of nine",max:100,options:{factor:9},objective:"I can multiply and divide by nine.",explanation:"Count five equal groups and four more groups. Add the two totals.",hints:["Build the equal groups with a familiar arrangement.","Split larger groups into known smaller groups, or reverse the multiplication to divide."],commonMistakes:["The equal-group size and the number of groups play different roles.","A division check should rebuild the original total."]},{id:"g2-56",number:56,name:"Table-trail checkpoint",world:"table-trails",type:"checkpoint",family:"mixed",skill:"Table-trail checkpoint",max:100,options:{checkpoint:true,scope:"table-trails"},objective:"I can choose facts for two through nine and follow operation order.",explanation:"Rebuild an unfamiliar fact from smaller known groups. Complete multiplication or division before separate addition or subtraction.",hints:["Choose the familiar model that fits this task.","Check the same answer with a second count, the opposite operation, or the unit relationship."],commonMistakes:["Answer the quantity indicated by the goal picture.","Keep the units and operation signs consistent."]},{id:"g2-57",number:57,name:"Groups of ten",world:"fact-stream",type:"lesson",family:"table",skill:"Groups of ten",max:100,options:{factor:10},objective:"I can multiply and divide by ten.",explanation:"Each group of ten can be represented by a ten-value coin. Reverse the exchange when dividing.",hints:["Build the equal groups with a familiar arrangement.","Split larger groups into known smaller groups, or reverse the multiplication to divide."],commonMistakes:["The equal-group size and the number of groups play different roles.","A division check should rebuild the original total."]},{id:"g2-58",number:58,name:"One group, one in each",world:"fact-stream",type:"lesson",family:"table",skill:"One group, one in each",max:100,options:{factor:1},objective:"I can multiply and divide by one.",explanation:"One group keeps the original quantity. Dividing by one puts one object in each group, so the number of groups equals the total.",hints:["Build the equal groups with a familiar arrangement.","Split larger groups into known smaller groups, or reverse the multiplication to divide."],commonMistakes:["The equal-group size and the number of groups play different roles.","A division check should rebuild the original total."]},{id:"g2-59",number:59,name:"Zero and empty groups",world:"fact-stream",type:"lesson",family:"zero",skill:"Zero and empty groups",max:100,options:{mode:"zero-facts",nonzeroDivisors:true},objective:"I can understand multiplication by zero and zero divided among groups.",explanation:"An empty group contains zero objects. Zero shared among a positive number of recipients gives zero to each.",hints:["Look at the empty collection or the empty groups.","Keep every recipient visible; zero objects leave every share empty."],commonMistakes:["Zero groups and groups with zero objects both have zero objects in total.","Division by zero is never allowed."]},{id:"g2-60",number:60,name:"Missing multiplication facts",world:"fact-stream",type:"lesson",family:"missing-fact",skill:"Missing multiplication facts",max:100,options:{mode:"missing-quantity"},objective:"I can find a missing total, group count, or group size.",explanation:"Use the quantities already shown to rebuild the collection. The blank may stand for a different part of the same relationship.",hints:["Identify the total, group count, and amount in each group.","Use the two known quantities to rebuild the missing one; reverse the operation to check."],commonMistakes:["The position of the blank determines which quantity is requested.","Use a nonzero group size when dividing."]},{id:"g2-61",number:61,name:"Brackets and operation order",world:"fact-stream",type:"lesson",family:"brackets",skill:"Brackets and operation order",max:100,options:{mode:"all-operations"},objective:"I can complete brackets and follow operation order.",explanation:"Complete brackets first. Then work through multiplication and division from left to right, followed by addition and subtraction from left to right.",hints:["Complete anything inside brackets first.","Next complete multiplication and division from left to right; then addition and subtraction from left to right."],commonMistakes:["Multiplication and division have equal priority.","Addition and subtraction have equal priority."]},{id:"g2-62",number:62,name:"Group picture stories",world:"fact-stream",type:"lesson",family:"group-story",skill:"Group picture stories",max:100,options:{mode:"total-share-or-group-count"},objective:"I can choose the correct meaning of multiplication or division.",explanation:"The picture goal shows whether you need the total, the amount in one group, or the number of groups.",hints:["Follow the picture from the start through each change.","Complete the first relationship, keep its result, then solve the next part."],commonMistakes:["A pictured goal may ask for a missing part rather than the final total.","Use each change once and keep track of what is known."]},{id:"g2-63",number:63,name:"Full groups and leftovers",world:"fact-stream",type:"lesson",family:"remainder",skill:"Full groups and leftovers",max:100,options:{mode:"group-and-remainder"},objective:"I can find complete groups and the leftover amount.",explanation:"Fill as many complete groups as possible. Any objects that cannot fill another group are the remainder.",hints:["Fill as many complete groups as possible.","Keep leftovers outside the groups and rebuild the total from full groups and leftovers."],commonMistakes:["The remainder must be smaller than the group size.","Do not count a partly filled group as a full group."]},{id:"g2-64",number:64,name:"Fact-stream checkpoint",world:"fact-stream",type:"checkpoint",family:"mixed",skill:"Fact-stream checkpoint",max:100,options:{checkpoint:true,scope:"fact-stream"},objective:"I can use basic facts, missing numbers, brackets, and remainders.",explanation:"Choose a familiar group or calculation model. Keep the group size and the leftover amount distinct.",hints:["Choose the familiar model that fits this task.","Check the same answer with a second count, the opposite operation, or the unit relationship."],commonMistakes:["Answer the quantity indicated by the goal picture.","Keep the units and operation signs consistent."]},{id:"g2-65",number:65,name:"Rebuild the total",world:"problem-patch",type:"lesson",family:"remainder-check",skill:"Rebuild the total",max:100,options:{mode:"rebuild"},objective:"I can choose the calculation that matches the groups.",explanation:"Multiplication counts the counters in full boxes. If there is a partly filled box, add only the counters it contains.",hints:["Count the full boxes and the counters in one full box.","Find that multiplication, then include the partly filled box if there is one."],commonMistakes:["Multiply the number of full boxes by the counters in one full box.","Do not treat a partly filled box as full; add only its actual counters."]},{id:"g2-66",number:66,name:"How many boxes?",world:"problem-patch",type:"lesson",family:"boxes",skill:"How many boxes?",max:100,options:{mode:"full-or-all"},objective:"I can distinguish full boxes from boxes needed for all objects.",explanation:"A full-box question counts only complete boxes. Fitting every object may require one extra partly filled box.",hints:["Check whether the goal asks for full boxes or space for every object.","Pack full boxes, then decide whether the leftovers need another box."],commonMistakes:["Leftovers do not create another full box.","Any leftovers need one more box when every object must fit."]},{id:"g2-67",number:67,name:"Split to multiply",world:"problem-patch",type:"lesson",family:"multiply-split",skill:"Split to multiply",max:100,options:{mode:"tens-and-ones",mentalOnly:true},objective:"I can multiply a number above ten by splitting it.",explanation:"Split the larger number into two easy parts. Multiply both parts by the other number, then add the results.",hints:["Split the larger number into two parts that are easy to multiply.","Multiply both parts by the same other number, then add the results."],commonMistakes:["Both split parts must be multiplied.","The split parts must add back to the original factor."]},{id:"g2-68",number:68,name:"Split to divide",world:"problem-patch",type:"lesson",family:"divide-split",skill:"Split to divide",max:100,options:{mode:"convenient-parts",mentalOnly:true},objective:"I can divide by splitting the total into easy parts.",explanation:"Split the total into two amounts that divide exactly by the given divisor. Divide both, then add the answers.",hints:["Split the total into two parts that each divide exactly.","Divide both parts by the same divisor, then join the quotients."],commonMistakes:["Keep the same divisor for both parts.","The chosen parts must add back to the original total."]},{id:"g2-69",number:69,name:"Operation machines",world:"problem-patch",type:"lesson",family:"machine",skill:"Operation machines",max:100,options:{mode:"four-operations"},objective:"I can apply a machine rule to a new input.",explanation:"Use the completed input and output pairs to identify the same operation. Apply it to the unfinished pair.",hints:["Compare each completed input with its output.","Find the same change in every row and apply it to the missing output or input."],commonMistakes:["One machine rule must fit all completed rows.","To find a missing input, reverse the machine operation."]},{id:"g2-70",number:70,name:"Mixed picture stories",world:"problem-patch",type:"lesson",family:"picture-story",skill:"Mixed picture stories",max:100,options:{structures:["groups-and-change","comparison-and-total","unknown-start"]},objective:"I can combine groups, changes, and comparisons.",explanation:"Complete one relationship at a time. Keep the first result and use it in the next pictured step.",hints:["Follow the picture from the start through each change.","Complete the first relationship, keep its result, then solve the next part."],commonMistakes:["A pictured goal may ask for a missing part rather than the final total.","Use each change once and keep track of what is known."]},{id:"g2-71",number:71,name:"Read the data",world:"problem-patch",type:"lesson",family:"data",skill:"Read the data",max:100,options:{mode:"table-pictogram-bar"},objective:"I can read a table, pictogram, or bar chart.",explanation:"Match each picture category with its row or bar. Follow the labelled scale when comparing quantities.",hints:["Match the picture category with its row or bar.","Read the value from the labelled scale, then compare or combine only the requested categories."],commonMistakes:["A graph marker may stand for more than one object; use its key.","Count from the baseline and keep the categories distinct."]},{id:"g2-72",number:72,name:"Problem-patch checkpoint",world:"problem-patch",type:"checkpoint",family:"mixed",skill:"Problem-patch checkpoint",max:100,options:{checkpoint:true,scope:"problem-patch"},objective:"I can solve practical grouping, calculation, and data tasks.",explanation:"Choose groups, splitting, a machine, or a chart to match the task. Check that your answer describes the requested quantity.",hints:["Choose the familiar model that fits this task.","Check the same answer with a second count, the opposite operation, or the unit relationship."],commonMistakes:["Answer the quantity indicated by the goal picture.","Keep the units and operation signs consistent."]},{id:"g2-73",number:73,name:"Kilograms and decagrams",world:"discovery",type:"lesson",family:"convert-mass",skill:"Kilograms and decagrams",max:100,options:{units:["kg","dkg"],maxResult:100},objective:"I can use kilograms and decagrams.",explanation:"One kilogram is one hundred decagrams. Equivalent weights balance even when the pieces differ.",hints:["Use the relationship one kilogram equals one hundred decagrams.","Match equal weights or combine decagrams to make a full kilogram."],commonMistakes:["Kilograms and decagrams use different unit sizes.","Equal weights balance even when their pieces differ."]},{id:"g2-74",number:74,name:"Litres and decilitres",world:"discovery",type:"lesson",family:"convert-capacity",skill:"Litres and decilitres",max:100,options:{units:["l","dl"],maxResult:100},objective:"I can convert between litres and decilitres.",explanation:"One litre is ten decilitres. Include the whole litres and any extra decilitres when converting.",hints:["Use the relationship 1 l = 10 dl.","Count in tens when changing litres to decilitres. Make groups of ten when changing back."],commonMistakes:["One litre is ten decilitres, not one hundred.","Keep both the full litres and the remaining decilitres."]},{id:"g2-75",number:75,name:"Find the shape",world:"discovery",type:"lesson",family:"shape",skill:"Find the shape",max:100,options:{mode:"properties",excludeRectangleForSquare:true},objective:"I can recognise flat shapes by their sides and corners.",explanation:"Trace sides and count corners. A square has four equal sides and four square corners, so it is also a special rectangle.",hints:["Trace every side and count the corners once.","Use equal-side marks and square-corner marks to identify the requested shape."],commonMistakes:["Turning a shape does not change its kind.","A square is also a rectangle; do not treat those descriptions as mutually exclusive."]},{id:"g2-76",number:76,name:"Mirrors and tiles",world:"discovery",type:"lesson",family:"reflection",skill:"Mirrors and tiles",max:100,options:{mode:"mirror-and-tiles"},objective:"I can complete a reflection and fit repeating tiles.",explanation:"Reflected parts lie equally far from opposite sides of the mirror line. Tiles cover an area without gaps or overlaps.",hints:["Find the mirror line or the edge of the region to cover.","Match reflected positions at equal distances, or fit tile edges without gaps or overlaps."],commonMistakes:["A reflection reverses the picture across the mirror line.","Sliding the same picture sideways does not make its reflection."]},{id:"g2-77",number:77,name:"Solids and building",world:"discovery",type:"lesson",family:"solid",skill:"Solids and building",max:100,options:{mode:"objects-and-block-models"},objective:"I can recognise familiar solids and match block models.",explanation:"Match a familiar object to a solid. For a block building, count the cubes or compare the towers.",hints:["For solids, look for flat faces, a curved surface and corners.","For buildings, follow each tower from bottom to top; count its cubes or match its height."],commonMistakes:["Match the whole object's shape, not just one flat face.","Count every cube once; matching towers must have the same height and position."]},{id:"g2-78",number:78,name:"Hundreds to one thousand",world:"discovery",type:"lesson",family:"hundreds",skill:"Hundreds to one thousand",max:1e3,options:{mode:"hundreds",guided:true},objective:"I can count in hundreds to one thousand.",explanation:"Each counter marked 100 is worth one hundred. Count in hundreds, once for each counter.",hints:["Read the value printed on each counter.","Count in steps of one hundred. Stop after the last counter."],commonMistakes:["One hundred-value counter is worth one hundred, not one.","Count each counter exactly once."]},{id:"g2-79",number:79,name:"Explore three-digit numbers",world:"discovery",type:"lesson",family:"place",skill:"Explore three-digit numbers",max:1e3,options:{mode:"build-locate-compare",guided:true},objective:"I can build, locate, and compare three-digit numbers.",explanation:"Separate the hundreds, tens, and ones. Each digit shows how many units belong to that place.",hints:["For counters, read each printed value; for a number line, check one interval.","Compare numbers from the hundreds down. On the number line, count in hundreds."],commonMistakes:["One hundred-value coin stands for one hundred, not one.","A zero digit means no coins in that position."]},{id:"g2-80",number:80,name:"Four final missions",world:"discovery",type:"final",family:"mixed",skill:"Four final missions",max:100,options:{scope:"core",missions:4,excludeLevels:[78,79]},objective:"I can use second-grade skills in four separate missions.",explanation:"Each mission revisits familiar core skills within one hundred. Correct the same answers until every answer is right.",hints:["Choose the familiar model that fits this task.","Check the same answer with a second count, the opposite operation, or the unit relationship."],commonMistakes:["Answer the quantity indicated by the goal picture.","Keep the units and operation signs consistent."],missions:[{id:"number",name:"Number paths",ranges:[[1,7],[9,15],[23,23]],questions:10,pass:10},{id:"calculate",name:"Calculation paths",ranges:[[17,21],[25,31],[41,47],[49,55],[57,63],[65,70]],questions:10,pass:10},{id:"everyday",name:"Everyday paths",ranges:[[22,22],[33,39],[71,71],[73,74]],questions:10,pass:10},{id:"shapes",name:"Shape and picture paths",ranges:[[6,7],[31,31],[62,62],[70,71],[75,77]],questions:10,pass:10}]}];const catalog=freeze({version:1,id:"grade-2",grade:2,theme:"Worlds",title:"2nd Grade",worlds,levels});root.TideGrade2Content=catalog;if(typeof module!=="undefined"&&module.exports)module.exports=catalog})(typeof window!=="undefined"?window:globalThis);
